contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // Ensure a clean state first: withdraw anything recorded (succeeds even if zero).
        c.withdrawBalance();
        uint beforeSecond = c.getBalance(address(this));
        // Deposit amount.
        c.addToBalance{value: amount}();
        // Withdraw everything (recorded balance is amount > 0, so it succeeds and zeroes it).
        c.withdrawBalance();
        uint afterWithdraw = c.getBalance(address(this));
        // Deposit again: recorded balance must be exactly amount, proving no residue survived the withdrawal.
        c.addToBalance{value: amount}();
        uint afterRedeposit = c.getBalance(address(this));
        assert(beforeSecond == 0 && afterWithdraw == 0 && afterRedeposit == amount);
    }
    receive() external payable { }
}

